const fs = require('fs');
const item = $input.first().json;

let prompt = fs.readFileSync('/prompts/rank.md', 'utf8');
prompt = prompt
  .replace('{{title}}', item.title || '')
  .replace('{{summary}}', item.summary || '')
  .replace('{{category}}', item.category || '')
  .replace('{{source}}', item.source_name || '')
  .replace('{{published_at}}', item.published_at || new Date().toISOString())
  .replace('{{word_count}}', item.word_count || 0);

return [{ json: { ...item, prompt } }];

const item = $input.first().json;
const original = $('Get Approved Articles').first().json;

let scores;
try { scores = JSON.parse(item.choices[0].message.content); } catch(e) { scores = { final_score: 0.5, recommendation: 'review' }; }

// Adjust for source reliability
const reliabilityBonus = (original.reliability || 0.8) * 0.05;
scores.final_score = Math.min(1, (scores.final_score || 0.5) + reliabilityBonus);

return [{ json: { article_id: original.id, ...scores } }];
